"use client";

import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/InterTight";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround, gshParams } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import {
  type ResolvedElement,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import {
  accentIndex,
  type CoolingTypeElementId,
  coolingTypeTimeline,
  DEFAULT_ACCENT_WORD,
  DEFAULT_TEXT,
  wordsOf,
} from "./timeline";

const inter = loadInter("normal", {
  weights: ["300"],
  subsets: ["latin"],
});
const serif = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface CoolingTypeProps {
  text?: string;
  accentWord?: string;
  hot?: string;
  accent?: string;
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the typed copy. Load it yourself; Inter Tight by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Strength of the heat glow around fresh letters; 0 turns it off. */
  glow?: number;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  startAt?: number;
  charFrames?: number;
  coolFrames?: number;
  seed?: number;
  /** Size of the copy, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  /**
   * Moves, trims or stretches single letters, the caret's finish and the
   * camera push, by the ids in `./timeline`. Frames on the scene timeline,
   * after `delay` and `speed`.
   */
  timing?: Timing<CoolingTypeElementId>;
}

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "aurora",
  background: "#eef2f4",
  colors: ["#d4e4ff", "#f3f5f7", "#cfeee6", "#e7e3fb"],
  blur: 0.85,
  warp: 0.35,
  seed: 4,
  grain: 0.16,
};

const THEMES = {
  dark: {
    ink: "#eef3f1",
    hot: "#7dffd9",
    accent: "#7de8c8",
    glow: 1,
    band: 0.3,
    ground: "kiruna" as GshPresetId | undefined,
    groundParams: undefined as Partial<GradientParams> | undefined,
    groundOffset: 5,
    scrim: "2,8,8",
    scrimAlpha: 0.72,
  },
  light: {
    ink: "#141618",
    hot: "#2f5bff",
    accent: "#2f5bff",
    glow: 0.45,
    band: 0.2,
    ground: undefined as GshPresetId | undefined,
    groundParams: LIGHT_GROUND as Partial<GradientParams> | undefined,
    groundOffset: 3,
    scrim: "238,242,244",
    scrimAlpha: 0.4,
  },
};

const FONT_PX = 200;
const TRACK = -0.028;
const COOL = Easing.bezier(0.33, 0, 0.2, 1);
const KEY = Easing.bezier(0.22, 1, 0.36, 1);
const CAMERA = Easing.bezier(0.87, 0, 0.13, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

type Measure = (s: string, serifFace: boolean) => number;

function buildMeasure(
  _version: number,
  fontFamily: string,
  fontWeight: number,
): Measure {
  const ctx = document.createElement("canvas").getContext("2d");
  const cache: Record<string, number> = {};
  return (s: string, serifFace: boolean) => {
    const k = `${serifFace ? 1 : 0}|${s}`;
    if (cache[k] === undefined) {
      if (!ctx) return s.length * 0.5;
      ctx.font = serifFace
        ? `italic 400 ${FONT_PX}px "${serif.fontFamily}"`
        : `${fontWeight} ${FONT_PX}px "${fontFamily}"`;
      const tr = serifFace ? -0.01 : TRACK;
      cache[k] = ctx.measureText(s).width / FONT_PX + tr * Array.from(s).length;
    }
    return cache[k];
  };
}

function useMeasure(fontFamily: string, fontWeight: number) {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("cooling-type: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      inter.waitUntilDone(),
      serif.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
      document.fonts.load(`italic 400 100px "${serif.fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle, fontFamily, fontWeight]);
  return useMemo(
    () => buildMeasure(version, fontFamily, fontWeight),
    [version, fontFamily, fontWeight],
  );
}

interface Ch {
  ch: string;
  x: number;
  w: number;
  line: number;
  serif: boolean;
  t: number;
  el: ResolvedElement<CoolingTypeElementId>;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function CoolingType(props: CoolingTypeProps) {
  const {
    text = DEFAULT_TEXT,
    accentWord = DEFAULT_ACCENT_WORD,
    hot,
    accent,
    ink,
    background,
    fontFamily = inter.fontFamily,
    fontWeight = 300,
    glow = 1,
    theme = "dark",
    ground,
    groundParams,
    scale = 1,
    delay = 0,
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  // The camera push runs over the clip without `speed`, as before.
  const tl = useTimeline(coolingTypeTimeline, props, durationInFrames, timing);
  const c = THEMES[theme];
  const glowK = c.glow * glow;
  const inkC = ink ?? c.ink;
  const hotC = hot ?? c.hot;
  const accC = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams = groundParams ?? (ground ? undefined : c.groundParams);
  const bg = gshParams(preset, gParams).background;
  const portrait = H > W * 1.1;
  const m = useMeasure(fontFamily, fontWeight);

  let content: ReactNode = <div />;
  if (m) {
    const words = wordsOf(text);
    const accIdx = accentIndex(words, accentWord);
    const isSerif = (wi: number) => wi === accIdx;
    const wordW = (wi: number) => m(words[wi], isSerif(wi));
    const space = m(" ", false);
    const maxW = (portrait ? 0.84 : 0.78) * W;
    const maxLines = portrait ? 5 : 2;
    let size = portrait ? W * 0.16 : H * 0.125;
    let rows: number[][] = [];
    const rowW = (row: number[]) =>
      row.reduce((a, wi, k) => a + wordW(wi) + (k > 0 ? space : 0), 0);
    for (let k = 0; k < 30; k++) {
      rows = [];
      let cur: number[] = [];
      words.forEach((_, wi) => {
        const next = [...cur, wi];
        if (cur.length > 0 && rowW(next) * size > maxW) {
          rows.push(cur);
          cur = [wi];
        } else {
          cur = next;
        }
      });
      if (cur.length > 0) rows.push(cur);
      if (
        rows.length <= maxLines &&
        rows.every((rw) => rowW(rw) * size <= maxW)
      )
        break;
      size *= 0.94;
    }
    const LH = size * 1.14;
    const blockW = Math.max(...rows.map(rowW)) * size;
    const x0 = (W - blockW) / 2;
    const top = H / 2 - (rows.length * LH) / 2;
    const lineY = (li: number) => top + LH * (li + 0.5);

    const chars: Ch[] = [];
    rows.forEach((rw, li) => {
      let x = x0;
      rw.forEach((wi, k) => {
        if (k > 0) {
          x += space * size;
        }
        const sf = isSerif(wi);
        const word = words[wi];
        Array.from(word).forEach((ch, ci) => {
          const pre = word.slice(0, ci);
          const cx = x + m(pre, sf) * size;
          const cw = m(ch, sf) * size;
          const el = tl.get(`char:${chars.length}`);
          chars.push({
            ch,
            x: cx,
            w: cw,
            line: li,
            serif: sf,
            t: el.start,
            el,
          });
        });
        x += wordW(wi) * size;
      });
    });
    const caretEl = tl.get("caret");
    const typedEnd = caretEl.start;
    const f = frame;

    const shownAt = (fr: number) => {
      let k = 0;
      while (k < chars.length && chars[k].t <= fr) k++;
      return k;
    };
    const caretAt = (fr: number) => {
      const k = shownAt(fr);
      if (k === 0) return { x: x0, li: 0 };
      const cur = chars[k - 1];
      const end = cur.x + cur.w;
      const prevEnd =
        k >= 2 && chars[k - 2].line === cur.line
          ? chars[k - 2].x + chars[k - 2].w
          : cur.x;
      const e = KEY(Math.min(1, (fr - cur.t) / cur.el.beat("slide")));
      return { x: prevEnd + (end - prevEnd) * e, li: cur.line };
    };

    const heatOf = (ch: Ch) => {
      const a = f - ch.t;
      const len = ch.el.length;
      return 1 - interpolate(a, [0, len], [0, 1], { ...CLAMP, easing: COOL });
    };

    const pct = (v: number) =>
      `${(Math.max(0, Math.min(1, v)) * 100).toFixed(1)}%`;

    const bands = rows.map((_, li) => {
      const warm = chars.filter(
        (ch) => ch.line === li && ch.t <= f && heatOf(ch) > 0.04,
      );
      if (warm.length === 0) return null;
      const peak = Math.max(...warm.map(heatOf));
      const left = warm[0].x - size * 0.06;
      const last = warm[warm.length - 1];
      const right = last.x + last.w + size * 0.08;
      return (
        <div
          key={`b${li}`}
          style={{
            position: "absolute",
            left,
            top: lineY(li) - LH * 0.46,
            width: Math.max(1, right - left),
            height: LH * 0.92,
            borderRadius: LH * 0.18,
            background: `linear-gradient(90deg, color-mix(in oklab, ${hotC} 0%, transparent) 0%, color-mix(in oklab, ${hotC} ${pct(c.band * peak)}, transparent) 100%)`,
            filter: `blur(${(size * 0.07).toFixed(2)}px)`,
          }}
        />
      );
    });

    const pushEl = tl.get("push");
    const pushAt = (fr: number) =>
      interpolate(fr, [pushEl.start, pushEl.end], [1, 1.04], {
        ...CLAMP,
        easing: CAMERA,
      });
    const push = pushAt(frame);
    // The camera's ease is very flat at both ends, so "moving" is the scale
    // step weighed at the frame's edge, against the neighbouring frames.
    const pushMoving =
      Math.abs(pushAt(frame + speed) - push) * W * 0.5 > 1e-3 ||
      Math.abs(push - pushAt(frame - speed)) * W * 0.5 > 1e-3;

    const glyphEls = chars.map((ch, i) => {
      if (ch.t > f) return null;
      const a = f - ch.t;
      const heat = heatOf(ch);
      const land = ch.el.beat("land");
      const e = KEY(Math.min(1, a / land));
      const target = ch.serif ? accC : inkC;
      const flare = ch.serif ? 1.4 : 1;
      const g = heat * glowK * flare;
      const shadow =
        g > 0.02
          ? `0 0 ${(size * 0.12 * g).toFixed(2)}px color-mix(in oklab, ${hotC} ${pct(0.9 * g)}, transparent), 0 0 ${(size * 0.42 * g).toFixed(2)}px color-mix(in oklab, ${hotC} ${pct(0.4 * g)}, transparent)`
          : undefined;
      return (
        <div
          key={`c${i}`}
          style={{
            position: "absolute",
            left: ch.x,
            top: lineY(ch.line) - size / 2,
            height: size,
            display: "flex",
            alignItems: "center",
            fontFamily: ch.serif ? serif.fontFamily : fontFamily,
            fontStyle: ch.serif ? "italic" : "normal",
            fontWeight: ch.serif ? 400 : fontWeight,
            fontSize: ch.serif ? size * 1.04 : size,
            lineHeight: 1,
            whiteSpace: "pre",
            color: `color-mix(in oklab, ${hotC} ${pct(heat)}, ${target})`,
            textShadow: shadow,
            opacity: Math.min(1, 0.35 + a / ch.el.beat("fade")),
            transform: `translateY(${((1 - e) * size * 0.1).toFixed(2)}px)${glide(a < land && !pushMoving)}`,
            filter:
              e < 0.98 ? `blur(${((1 - e) * 4).toFixed(2)}px)` : undefined,
          }}
        >
          {ch.ch}
        </div>
      );
    });

    const cur = caretAt(f);
    const back = caretAt(f - 3);
    const typing = f <= typedEnd + caretEl.beat("trail");
    const vel = cur.li === back.li ? Math.max(0, (cur.x - back.x) / 3) : 0;
    const trail = typing
      ? Math.min(size * 2.6, Math.max(size * 0.25, vel * 7))
      : interpolate(
          f,
          [
            typedEnd + caretEl.beat("trail"),
            typedEnd + caretEl.beat("trailEnd"),
          ],
          [size * 0.25, 0],
          CLAMP,
        );
    const caretHeat = typing
      ? 1
      : 1 -
        interpolate(f, [typedEnd, caretEl.end], [0, 1], {
          ...CLAMP,
          easing: COOL,
        });
    const blink =
      typing || Math.floor((f - typedEnd) / caretEl.beat("blink")) % 2 === 1;
    const caretW = Math.max(2, size * 0.045);
    const caretH = size * 1.02;
    const caretC = `color-mix(in oklab, ${hotC} ${pct(caretHeat)}, ${inkC})`;
    const cx = cur.x + size * 0.05;
    const cy = lineY(cur.li);
    const caret = (
      <>
        {trail > 1 ? (
          <div
            style={{
              position: "absolute",
              left: cx - trail,
              top: cy - caretH * 0.2,
              width: trail,
              height: caretH * 0.4,
              borderRadius: caretH,
              background: `linear-gradient(90deg, color-mix(in oklab, ${hotC} 0%, transparent) 0%, color-mix(in oklab, ${hotC} ${pct(0.55 * glowK + 0.15)}, transparent) 100%)`,
              filter: `blur(${(size * 0.09).toFixed(2)}px)`,
            }}
          />
        ) : null}
        <div
          style={{
            position: "absolute",
            left: cx,
            top: cy - caretH / 2,
            width: caretW,
            height: caretH,
            borderRadius: caretW,
            background: caretC,
            opacity: blink ? 1 : 0,
            boxShadow: `0 0 ${(size * 0.18 * caretHeat * glowK).toFixed(2)}px color-mix(in oklab, ${hotC} ${pct(0.8 * caretHeat)}, transparent)`,
          }}
        />
      </>
    );

    content = (
      <AbsoluteFill
        style={{
          // Rounded only at rest: a scale stepped by 1e-5 moves the frame's
          // edge in 0.01px steps of its own while the camera pushes.
          transform: `scale(${pushMoving ? push : push.toFixed(5)})${glide(pushMoving)}`,
          transformOrigin: "50% 50%",
        }}
      >
        {bands}
        {glyphEls}
        {caret}
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill
      style={{
        background: background === undefined ? bg : undefined,
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <>
          <GshGround
            preset={preset}
            params={gParams}
            timeOffset={c.groundOffset}
            timeScale={0.5}
          />
          <AbsoluteFill
            style={{
              background: `radial-gradient(${portrait ? "95% 50%" : "72% 62%"} at 50% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
            }}
          />
        </>
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={scale}>{content}</ScaleLayer>
    </AbsoluteFill>
  );
}

export default CoolingType;

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The line typing itself letter by letter, each letter landing hot and
// cooling to the ink, the accent word typed after a breath; then the caret
// cooling and its trail fading; under it all a slow camera push over the
// clip. Frames on the 30 fps scene timeline, after `delay` and `speed`. The
// ids are public: a saved `timing` prop refers to them.

export type CoolingTypeElementId = "push" | `char:${number}` | "caret";

export interface CoolingTypeTimingProps {
  text?: string;
  accentWord?: string;
  startAt?: number;
  charFrames?: number;
  coolFrames?: number;
  seed?: number;
}

export const DEFAULT_TEXT = "What if your launch video could write itself?";
export const DEFAULT_ACCENT_WORD = "itself?";

export const BEAT = {
  start: -3,
  breath: 8,
  accentRate: 1.25,
};
/** A letter fades in over `FADE`, drops into place over `LAND`. */
const FADE = 1.5;
const LAND = 4;
/** The caret slides to a new letter over `SLIDE`. */
const SLIDE = 2;
/** The accent word cools this much slower. */
const SERIF_COOL = 1.8;
/** After the last letter the caret keeps typing for `TRAIL`, its trail fading by `TRAIL_END`. */
const TRAIL = 2;
const TRAIL_END = 10;
/** The caret blinks every `BLINK` frames once typing ends. */
const BLINK = 15;

// Remotion's `random()` for a string seed, so the jitter in the typing
// rhythm stays exactly as it was.
function mulberry32(a: number) {
  let t = a + 1831565813;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function seeded(seed: string) {
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash << 5) - hash + seed.charCodeAt(i);
    hash |= 0;
  }
  return mulberry32(hash);
}

export function wordsOf(text: string) {
  return text.split(" ").filter((w) => w.length > 0);
}

/** Index of the accent word, set in the serif; -1 when none. */
export function accentIndex(words: string[], accentWord: string) {
  return accentWord ? words.lastIndexOf(accentWord) : -1;
}

// `push` is the camera's slow push over the whole clip. `char:<i>` is letter
// `i` (spaces not counted): it appears at its start and cools over its
// length; its `fade`, `land` and `slide` beats time its arrival. The letters
// form a chain, each following the one before. `caret` starts at the last
// letter: typing continues to its `trail` beat, the trail fades by
// `trailEnd`, the caret cools over its length and blinks every `blink`.
// `length` here is the clip without `speed`, as the push counts it.
export const coolingTypeTimeline = defineTimeline<
  CoolingTypeElementId,
  CoolingTypeTimingProps
>(
  (
    {
      text = DEFAULT_TEXT,
      accentWord = DEFAULT_ACCENT_WORD,
      startAt = BEAT.start,
      charFrames = 1.6,
      coolFrames = 20,
      seed = 5,
    },
    { length },
  ) => {
    const words = wordsOf(text);
    const accIdx = accentIndex(words, accentWord);
    const letters: { ch: string; t: number; serif: boolean }[] = [];
    let t = startAt;
    let total = 0;
    total += words.reduce((a, w) => a + w.length + 1, 0);
    let n = 0;
    words.forEach((word, wi) => {
      const sf = wi === accIdx;
      if (sf) t += BEAT.breath;
      Array.from(word).forEach((ch) => {
        letters.push({ ch, t, serif: sf });
        const accel = 1.2 - 0.45 * (n / Math.max(1, total));
        const jitter = (seeded(`ct-${seed}-${n}`) - 0.5) * 0.9;
        let step = sf ? BEAT.accentRate : charFrames * accel + jitter;
        if (/[,.;:!?]/.test(ch)) step += 4;
        t += Math.max(0.6, step);
        n++;
      });
      t += sf ? 0 : charFrames * 0.9;
      n++;
    });
    const typedEnd =
      letters.length > 0 ? letters[letters.length - 1].t : startAt;

    const elements: TimelineElement<CoolingTypeElementId>[] = [
      { id: "push", lane: "Camera", label: "push", start: 0, length },
      ...letters.map(
        (l, i): TimelineElement<CoolingTypeElementId> => ({
          id: `char:${i}`,
          lane: "Text",
          label: l.ch,
          start: l.t,
          length: l.serif ? coolFrames * SERIF_COOL : coolFrames,
          follows: i > 0 ? `char:${i - 1}` : undefined,
          beats: { fade: FADE, land: LAND, slide: SLIDE },
        }),
      ),
      {
        id: "caret",
        lane: "Caret",
        label: "caret",
        start: typedEnd,
        length: coolFrames,
        follows: letters.length > 0 ? `char:${letters.length - 1}` : undefined,
        beats: { trail: TRAIL, trailEnd: TRAIL_END, blink: BLINK },
      },
    ];
    return elements.sort((a, b) => a.start - b.start);
  },
);
